node -e '
const fs=require("fs");
const reports={north:{count:10,units:90,weighted:167},south:{count:10,units:94,weighted:171},east:{count:10,units:98,weighted:209},west:{count:10,units:85,weighted:145}};
const out={};let allMatch=true;
for(const r of ["north","south","east","west"]){
  const raw=fs.readFileSync(r+".json","utf8");
  const data=JSON.parse(raw);
  if(!Array.isArray(data)) throw new Error(r+": not an array");
  const count=data.length;
  const units=data.reduce((a,x)=>a+x.units,0);
  const weighted=data.reduce((a,x)=>a+x.units*x.weight,0);
  const bad=data.filter(x=>typeof x.units!=="number"||typeof x.weight!=="number");
  const rep=reports[r];
  const match=count===rep.count&&units===rep.units&&weighted===rep.weighted;
  if(!match) allMatch=false;
  out[r]={count,units,weighted};
  console.log(`${r}: records=${count} nonNumericFields=${bad.length} units=${units} weighted=${weighted} | inspector ${rep.count}/${rep.units}/${rep.weighted} | ${match?"MATCH":"MISMATCH"}`);
  console.log(`   per-record id:units*weight = `+data.map(x=>`${x.id}:${x.units}*${x.weight}=${x.units*x.weight}`).join(", "));
}
const gu=Object.values(out).reduce((a,v)=>a+v.units,0);
const gw=Object.values(out).reduce((a,v)=>a+v.weighted,0);
console.log("\ngrand_units="+gu+" grand_weighted="+gw);
console.log("allFourMatch="+allMatch);
'
